    fa: return true;
}

nativeHeapOverflowV48 {
    identity(bytes >> u64) -> u64 { return bytes; }
    run() -> int {
        a >> p<byte> <- alloc(identity(0xFFFFFFFFFFFFFFFF));
        b >> p<byte> <- calloc(identity(0x100000000),identity(0x100000000));
        c >> p<byte> <- calloc(1,identity(0xFFFFFFFFFFFFFFFF));
        ok >> bool <- a == null && b == null && c == null;
        free(a); free(b); free(c);
        return ok ? 75 : 1;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapNestedV48 {
    make(bytes >> u64) -> p<byte> { return alloc(bytes); }
    release(pointer >> p<byte>) -> bool { return free(pointer); }
    run() -> int {
        left >> p<u64> <- cast<u64>(make(8));
        right >> p<u64> <- cast<u64>(make(8));
        if (left == null || right == null) { release(left); release(right); return 1; }
        wr(left,0x100000000); wr(right,0x10000000A);
        value >> u64 <- rd(left)+rd(right);
        return release(left) && release(right) && value == 0x20000000A ? 76 : 2;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapShadowV48 {
    alloc(value >> int) -> int { return value+1; }
    calloc(left >> int, right >> int) -> int { return left+right; }
    free(value >> int) -> int { return value-1; }
    realloc(left >> int, right >> int) -> int { return left*right; }
    run() -> int { return alloc(7)+calloc(9,10)+free(21)+realloc(3,10); }
    ref main ->> run;
    fa: return true;
}

nativeLayoutV49 {
    type:
        Packet {
            public:
                tag >> int;
                flags >> byte;
            layout:
                repr(C);
                align(16);
        }
        Nested {
            public:
                prefix >> byte;
                packet >> Packet;
                samples >> array<word, 3>;
                link >> p<Nested>;
        }
        Wire {
            public:
                firstByte >> byte;
                value >> u64;
            layout:
                packed;
        }
        Choice union {
            public:
                value >> u64;
                data >> array<byte, 17>;
        }
        Tail {
            public:
                count >> int;
                data >> array<byte, 0>;
            layout:
                flexible(data);
        }
        Large {
            public:
                data >> array<byte, 1024>;
            layout:
                align(64);
        }

    fn:
        run() -> int {
            if (sizeOf(Packet) != 16 || alignOf(Packet) != 16) return 1;
            if (offsetOf<Packet>(tag) != 0 || offsetOf(Packet, flags) != 4) return 2;
            if (sizeOf(Nested) != 48 || alignOf(Nested) != 16) return 3;
            if (offsetOf<Nested>(packet) != 16 || offsetOf<Nested>(samples) != 32) return 4;
            if (offsetOf<Nested>(link) != 40) return 5;
            if (sizeOf(Wire) != 9 || alignOf<Wire>() != 1 || offsetOf<Wire>(value) != 1) return 6;
            if (sizeOf(Choice) != 24 || offsetOf<Choice>(data) != 0) return 7;
            if (sizeOf(Tail) != 4 || offsetOf<Tail>(data) != 4) return 8;
            if (sizeOf(Large) != 1024 || alignOf(Large) != 64) return 9;
            memory >> p<byte> <- alloc(sizeOf(Nested));
            if (memory == null) return 10;
            tagSlot >> p<int> <- cast<int>(off(memory, offsetOf<Nested>(packet)));
            wr(tagSlot, 42);
            if (rd(tagSlot) != 42) { free(memory); return 11; }
            free(memory);
            return 91;
        }

    ref main ->> run;
    fa:
        return true;
}

